export function wrapWithRowLevelNamespace(
  adapter: Adapter,
  config: RowLevelNamespaceConfig,
): Adapter {
  if (!config.enabled) return adapter;

  const wrappedBase = createNamespaceWrappedBase(adapter, config);

  const wrapped: Adapter = {
