+  const canonical = parseToolCalls(message.toolCalls);
+  const compatibility = parseToolCalls(message.tool_calls);
+  if (canonical?.length && compatibility?.length) {
+    if (stableToolCalls(canonical) !== stableToolCalls(compatibility)) {
