        throw new Error("SENDFN_MAILBOX_SUBJECT_INVALID");
      if (!request.text && !request.html)
        throw new Error("SENDFN_MAILBOX_CONTENT_REQUIRED");
      assertCustomEmailHeaders(request.headers);
