        if (
          !file.filename ||
          /[\r\n]/.test(file.filename) ||
          (file.encoding &&
            !["base64", "utf8", "utf-8"].includes(file.encoding))
        )
          throw new Error("SENDFN_MAILBOX_ATTACHMENT_INVALID");
