          parts.push(
            `Content-Type: ${file.type}\r\nContent-Disposition: attachment; filename*=UTF-8''${encodeURIComponent(file.filename)}\r\nContent-Transfer-Encoding: base64\r\n\r\n${fold(base64(file.bytes))}`,
          );
