    },
    sendEmail,
    async sendBulkEmail(requests) {
      const results = [];
      for (const request of requests) results.push(await sendEmail(request));
      return results;
    },
    validateEmail: isBareEmail,
    isHealthy: options.isConnected,
    async close() {},
  };
