  async listNamespaces(input: { tenantId?: string } = {}): Promise<NamespaceRecord[]> {
    const rows = await this.db.findMany<NamespaceRecord>({
      model: "secfn_namespaces",
      where: input.tenantId ? [{ field: "tenantId", operator: "eq", value: input.tenantId }] : [],
      orderBy: [{ field: "label", direction: "asc" }],
      limit: 1000,
    });
    if (rows.length > 0) return rows;
    return [await this.ensureNamespace({ tenantId: input.tenantId, namespace: DEFAULT_NAMESPACE, createdBy: "system" })];
  }

  async createNamespace(input: CreateNamespaceInput): Promise<NamespaceRecord> {
    const slug = normalizeSlug(input.slug);
    if (!slug) throw new SecFnValidationError("Namespace slug is required");
    const existing = await this.findNamespace({ tenantId: input.tenantId, namespace: slug });
    if (existing) throw new SecFnValidationError("Namespace already exists", { slug });
    const now = nowIso();
    return this.db.create<NamespaceRecord>({
      model: "secfn_namespaces",
      data: {
        id: generateId("ns"),
        tenantId: input.tenantId,
        slug,
        label: cleanString(input.label) ?? slug,
        description: cleanString(input.description),
        createdBy: input.createdBy,
        createdAt: now,
        updatedAt: now,
        metadata: input.metadata,
      } as unknown as Record<string, unknown>,
    });
  }

  async updateNamespace(id: string, input: UpdateNamespaceInput): Promise<NamespaceRecord> {
    const existing = await this.getNamespace(id);
  let calls = 0;
  const secfn = createSecFnServer({
    db: new MemoryAdapter(),
    encryption: { masterKey: "test" },
    context: { tenantId: "t" },
    namespaceProvider: () => {
      calls++;
      return calls === 1 ? undefined : "unexpected";
    },
    authorize: async () => true,
  });
  const response = await secfn.router.handle(
    new Request("https://test/secfn/admin/secrets"),
  );
  expect(response.status).toBe(200);
  expect(calls).toBe(1);
});

it("uses an isolated metrics snapshot without wall-clock sleeps", async () => {
  const { db, secfn } = createServer();
  await db.create({model:"secfn_audit_events",data:{id:"old",timestamp:"2000-01-01",type:"original",severity:"info"}});
  const transaction = db.transaction.bind(db);
  let inserted = false;
  db.transaction = (callback, options) => transaction(async snapshot => {
    if (!inserted) {
      inserted = true;
      await db.create({model:"secfn_audit_events",data:{id:"late",timestamp:"1999-01-01",type:"late",severity:"info"}});
    }
    return callback(snapshot);
  }, options);
  expect((await secfn.audit.getMetrics()).totalEvents).toBe(1);
  expect((await secfn.audit.getMetrics()).totalEvents).toBe(2);
});

