import type { AtomicKVStoreAdapter } from '@superfunctions/db';

interface Claim {
  state: 'idle' | 'running' | 'uncertain';
  token: string;
  expiresAt: number;
}
/** Shared admission control. Expired dispatched work is never automatically replayed. */
export class ExecutionCoordinator {
  private readonly now: () => number;
  constructor(
    private readonly store: AtomicKVStoreAdapter,
    private readonly options: { prefix?: string; leaseMs?: number; now?: () => number } = {}
  ) {
    if (!store.compareAndSet) throw new Error('EXECUTION_ATOMIC_CAS_REQUIRED');
    if (!Number.isFinite(options.leaseMs ?? 60_000) || (options.leaseMs ?? 60_000) <= 0)
      throw new Error('EXECUTION_INVALID_LEASE');
    this.now = options.now ?? Date.now;
  }

  async run<T>(key: string, work: () => Promise<T>): Promise<T> {
    const storageKey = this.key(key);
    const previous = await this.store.get(storageKey);
    const claim: Claim | null = previous ? JSON.parse(previous) : null;
    if (claim?.state === 'running' && claim.expiresAt > this.now())
      throw new Error('EXECUTION_IN_PROGRESS');
    if (claim && claim.state !== 'idle') throw new Error('EXECUTION_OUTCOME_UNCERTAIN');
    const owned: Claim = {
      state: 'running',
      token: crypto.randomUUID(),
      expiresAt: this.now() + (this.options.leaseMs ?? 60_000),
    };
    const serialized = JSON.stringify(owned);
    if (
      !(await this.store.compareAndSet!({ key: storageKey, expected: previous, value: serialized }))
        .updated
    )
      throw new Error('EXECUTION_IN_PROGRESS');
    try {
      const result = await work();
      const released = await this.store.compareAndSet!({
        key: storageKey,
        expected: serialized,
        value: JSON.stringify({ ...owned, state: 'idle' }),
      });
      if (!released.updated) throw new Error('EXECUTION_OWNERSHIP_LOST');
      return result;
    } catch (error) {
      await this.store.compareAndSet!({
        key: storageKey,
        expected: serialized,
        value: JSON.stringify({ ...owned, state: 'uncertain' }),
      });
      throw error;
    }
  }

  async inspect(key: string): Promise<Claim | null> {
    const value = await this.store.get(this.key(key));
    return value ? JSON.parse(value) : null;
  }

  /** Call only after stopping the former worker and reconciling its provider effects/checkpoints. */
  async reconcile(key: string, expectedToken: string): Promise<void> {
    const storageKey = this.key(key);
    const value = await this.store.get(storageKey);
    const claim: Claim | null = value ? JSON.parse(value) : null;
    if (
      !claim ||
      claim.token !== expectedToken ||
      claim.state === 'idle' ||
      (claim.state === 'running' && claim.expiresAt > this.now())
    )
      throw new Error('EXECUTION_RECONCILIATION_CONFLICT');
    if (
      !(
        await this.store.compareAndSet!({
          key: storageKey,
          expected: value,
          value: JSON.stringify({ ...claim, state: 'idle' }),
        })
      ).updated
    )
      throw new Error('EXECUTION_RECONCILIATION_CONFLICT');
  }

  private key(value: string) {
    if (!value) throw new Error('EXECUTION_KEY_REQUIRED');
    return `${this.options.prefix ?? 'plugfn:execution:'}${value}`;
  }
}
import { z } from 'zod';
import type { Action, ActionContract } from '../types/action.js';
import { redactTelemetry } from '../security/redaction.js';

export const actionContractSchema = z
  .object({
    version: z.string().regex(/^\d+\.\d+\.\d+$/),
    effect: z.enum(['read', 'write', 'destructive', 'unknown']),
    requiredScopes: z.array(z.string().min(1)),
    resources: z.array(
      z.object({ kind: z.string().min(1), parameter: z.string().min(1).optional() }).strict()
    ),
    sensitiveKeys: z.array(z.string().min(1)),
    pagination: z
      .object({
        kind: z.enum(['none', 'cursor', 'offset', 'page']),
        maxPageSize: z.number().int().positive().optional(),
        cursorParameter: z.string().min(1).optional(),
      })
      .strict(),
    retry: z.enum(['never', 'safe', 'provider-key']),
    idempotencyKeyParameter: z.string().min(1).optional(),
  })
  .strict()
  .superRefine((value, ctx) => {
    if (value.retry === 'provider-key' && !value.idempotencyKeyParameter) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: 'Provider-key retries require a key parameter',
      });
    }
    if (value.effect === 'unknown' && value.retry !== 'never') {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: 'Unknown effects cannot opt into retries',
      });
    }
  });

export function resolveActionContract(action: Action): ActionContract {
  return actionContractSchema.parse(
    action.contract ?? {
      version: '0.0.0',
      effect: 'unknown',
      requiredScopes: [],
      resources: [],
      sensitiveKeys: [],
      pagination: { kind: 'none' },
      retry: 'never',
    }
  );
}

/** Input/output JSON schemas are supplied by the consumer's schema converter. */
export async function createActionManifest(
  provider: string,
  action: Action,
  schemas: { input: unknown; output: unknown }
) {
  const manifest = {
    provider,
    action: action.name,
    contract: resolveActionContract(action),
    inputSchema: schemas.input,
    outputSchema: schemas.output,
  };
  const canonical = canonicalJson(manifest);
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(canonical));
  const hash = Array.from(new Uint8Array(digest), (byte) =>
    byte.toString(16).padStart(2, '0')
  ).join('');
  return { ...manifest, hash: `sha256-${hash}` };
}

export function redactActionTelemetry<T>(action: Action, value: T): T {
  return redactTelemetry(value, { sensitiveKeys: resolveActionContract(action).sensitiveKeys });
}

function canonicalJson(value: unknown, depth = 0): string {
  if (depth > 128) throw new Error('Manifest nesting exceeds limit or contains a cycle');
  if (value === null || typeof value === 'string' || typeof value === 'boolean')
    return JSON.stringify(value);
  if (typeof value === 'number' && Number.isFinite(value)) return JSON.stringify(value);
  if (Array.isArray(value))
    return `[${value.map((item) => canonicalJson(item, depth + 1)).join(',')}]`;
  if (value && typeof value === 'object' && Object.getPrototypeOf(value) === Object.prototype) {
    return `{${Object.keys(value)
      .sort(compareCanonicalKeys)
      .map(
        (key) =>
          `${JSON.stringify(key)}:${canonicalJson((value as Record<string, unknown>)[key], depth + 1)}`
      )
      .join(',')}}`;
  }
  throw new Error('Manifest must contain JSON values only');
}

// Explicitly preserve the default UTF-16 ordering; localeCompare would change manifest hashes.
function compareCanonicalKeys(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}
