it('prevents runtime query namespace from overriding namespaceProvider', async () => {
  const secfn = createSecFnServer({ db: new MemoryAdapter(), encryption: { masterKey: 'test' }, context: { tenantId: 'tenant-a' }, namespaceProvider: () => 'workspace-a', authorize: async () => true });
import type { Adapter, TransactionAdapter, WhereClause } from "@superfunctions/db";
import { generateId, nowIso } from "@secfn/core/id";
import type { SecurityAuditEvent, SecurityMetrics, SecFnLogger } from "@secfn/core";
import type { AuditWriteInput } from "./types.js";

export interface AuditServiceOptions {
  db: Adapter;
  logger?: SecFnLogger;
  sink?: (event: SecurityAuditEvent) => void | Promise<void>;
}

export class AuditService {
  constructor(private readonly options: AuditServiceOptions) {}

  async write(input: AuditWriteInput): Promise<SecurityAuditEvent> {
    const event: SecurityAuditEvent = {
      id: generateId("event"),
      timestamp: nowIso(),
      type: input.type,
      severity: input.severity,
      tenantId: input.tenantId,
      namespaceId: input.namespaceId,
      namespace: input.namespace,
      environmentId: input.environmentId,
      environment: input.environment,
      actorId: input.actorId,
      ip: input.ip,
      userAgent: input.userAgent,
      resource: input.resource,
      action: input.action,
      requestId: input.requestId,
      metadata: input.metadata ?? {},
      resolved: false,
    };

    await this.options.db.create({
      model: "secfn_audit_events",
      data: event as unknown as Record<string, unknown>,
    });

    // The durable event has committed. Secondary delivery cannot fail the mutation.
    try {
      const summary = sanitizeForLog(event);
      if (event.severity === "critical" || event.severity === "high") {
        this.options.logger?.warn("secfn security event", summary);
      } else { this.options.logger?.info("secfn security event", summary); }
    } catch { /* A host logger must not change committed operation semantics. */ }
    try { await this.options.sink?.(event); }
    catch {
      try { this.options.logger?.warn("secfn audit sink delivery failed", { eventId: event.id }); } catch { /* Durable event remains available. */ }
    }
    return event;
  }

  async queryEvents(query: {
    type?: string;
    severity?: string;
    tenantId?: string;
    namespace?: string;
    actorId?: string;
    resolved?: boolean;
    limit?: number;
  } = {}): Promise<SecurityAuditEvent[]> {
    const where: WhereClause[] = [];
    if (query.type) where.push({ field: "type", operator: "eq", value: query.type });
    if (query.severity) where.push({ field: "severity", operator: "eq", value: query.severity });
    if (query.tenantId) where.push({ field: "tenantId", operator: "eq", value: query.tenantId });
    if (query.namespace) where.push({ field: "namespace", operator: "eq", value: query.namespace });
    if (query.actorId) where.push({ field: "actorId", operator: "eq", value: query.actorId });
    if (query.resolved !== undefined) where.push({ field: "resolved", operator: "eq", value: query.resolved });
    return this.options.db.findMany<SecurityAuditEvent>({
      model: "secfn_audit_events",
      where,
      orderBy: [{ field: "timestamp", direction: "desc" }],
      limit: query.limit ?? 100,
    });
  }

  async logEvent(input: AuditWriteInput): Promise<string> {
    return (await this.write(input)).id;
  }

  async getRecentEvents(limit = 100): Promise<SecurityAuditEvent[]> {
    return this.queryEvents({ limit });
  }

  async getCriticalEvents(limit = 100): Promise<SecurityAuditEvent[]> {
    return this.queryEvents({ severity: "critical", limit });
  }

  async getUnresolvedEvents(limit = 100): Promise<SecurityAuditEvent[]> {
    return this.queryEvents({ resolved: false, limit });
  }

  async resolveEvent(id: string, input: { resolvedBy: string; notes?: string }): Promise<void> {
    await this.options.db.update({
      model: "secfn_audit_events",
      where: [{ field: "id", operator: "eq", value: id }],
      data: {
        resolved: true,
        resolvedAt: nowIso(),
        resolvedBy: input.resolvedBy,
        notes: input.notes,
      },
    });
  }

  async getMetrics(): Promise<SecurityMetrics> {
    if (!this.options.db.capabilities.transactions.configurableIsolation || !this.options.db.capabilities.transactions.isolation?.includes("repeatable_read")) {
      throw new Error("Audit metrics require repeatable_read transaction support");
    }
    return this.options.db.transaction(db => this.collectMetrics(db), { isolationLevel: "repeatable_read" });
  }

  private async collectMetrics(db: TransactionAdapter): Promise<SecurityMetrics> {
    let totalEvents = 0;
    let afterId: string | undefined;
    const eventsByType: Record<string, number> = {};
    const eventsBySeverity: Record<string, number> = {};
    const actors = new Map<string, number>();
    adminRoute("PATCH", "/admin/secret-sets/:id/members/:memberId", "secret-set-members:update", async (request, ctx) => {
      const body = await readJson<Record<string, unknown>>(request);
      return ok(await services.vault.updateSecretSetMember(ctx.params.memberId, {
        secretId: asOptionalString(body.secretId),
        alias: body.alias === null ? null : asOptionalString(body.alias),
      }));
    }),
    adminRoute("DELETE", "/admin/secret-sets/:id/members/:memberId", "secret-set-members:delete", async (_request, ctx) => {
      await services.vault.removeSecretSetMember(ctx.params.memberId);
      return emptyOk();
    }),
    adminRoute("POST", "/admin/service-tokens", "service-tokens:create", async (request, ctx) => {
      const body = await readJson<Record<string, unknown>>(request);
      return ok(await services.vault.createServiceToken({
        name: requiredString(body.name ?? ""),
        scopes: Array.isArray(body.scopes) ? body.scopes.map(String) : [],
        expiresAt: asOptionalString(body.expiresAt),
        createdBy: ctx.actorId ?? "system",
        ...(await scope(ctx)),
      }), { status: 201 });
    }),
    adminRoute("POST", "/admin/service-tokens/:id/revoke", "service-tokens:revoke", async (_request, ctx) => {
      await services.vault.revokeServiceToken(ctx.params.id, ctx.actorId ?? "system");
      return emptyOk();
    }),
    adminRoute("GET", "/admin/audit-events", "audit-events:list", async (_request, ctx) => {
      return ok(await services.audit.queryEvents({
        tenantId: ctx.tenantId ?? ctx.query.get("tenantId") ?? undefined,
        namespace: ctx.namespace ?? ctx.query.get("namespace") ?? undefined,
        type: ctx.query.get("type") ?? undefined,
        severity: ctx.query.get("severity") ?? undefined,
        limit: Number(ctx.query.get("limit") ?? 100),
      }));
