  $ref?: string;
  type?: string;
  format?: string;
  enum?: string[];
  properties?: Record<string, Schema>;
  items?: Schema;
  required?: boolean | string[];
  additionalProperties?: Schema;
  minimum?: string | number;
  maximum?: string | number;
  location?: string;
