      await this.persistTrace({
        kind: Array.isArray(input) ? "stream_chat" : "stream_completion",
        traceId,
        request: Array.isArray(input)
          ? { messages: input, metadata: options.metadata }
          : { prompt: input, metadata: options.metadata },
