        file,
        line: location.line,
        column: location.column,
        match: value,
        redactedMatch: redactSecret(value),
        fingerprint: fingerprintFinding({
          ruleId: this.id,
          file,
          line: location.line,
          column: location.column,
          value,
        }),
        context: contextForLine(content, location.line),
      });
    }
    return findings;
  }
}

