        { role: "tool", tool_call_id: "provider-call", content: "{}" },
      ],
    });
    expect(
      JSON.parse(fetchImpl.mock.calls[1][1].body).contents[2].parts[0]
        .functionResponse.id,
    ).toBe("provider-call");
  });
