  readonly code: string;
  readonly provider?: string;
  readonly metadata: Record<string, unknown>;

  constructor(
    message: string,
    options: {
      code: string;
      provider?: string;
      metadata?: Record<string, unknown>;
      cause?: unknown;
    }
  ) {
    super(message, options.cause ? { cause: options.cause } : undefined);
