      // This keeps the eventual error response inside upstream middleware such
      // as observability, so it can still finalize headers and completion hooks.
      return await middleware(request, context, next);
    } catch (error) {
      if (!onError) throw error;
      return onError(error);
    }
  };

  return next();
}

/**
 * Combine multiple middleware arrays into one
 */
export function combineMiddleware<TContext>(
  ...middlewareArrays: (Middleware<TContext>[] | undefined)[]
): Middleware<TContext>[] {
  return middlewareArrays.filter((arr): arr is Middleware<TContext>[] => !!arr).flat();
}
